import json, os
from pathlib import Path
from typing import Optional

CACHE_DIR = Path.home() / ".multi-ai-cache"
CACHE_DIR.mkdir(exist_ok=True)

def cache_path(session_id: str) -> str:
    return str(CACHE_DIR / f"{session_id}.json")

def cache_load(session_id: str) -> Optional[list]:
    p = cache_path(session_id)
    if os.path.exists(p):
        with open(p) as f:
            return json.load(f)
    return None

def cache_save(session_id: str, messages: list) -> None:
