import requests, os
from pathlib import Path
from .base import ChatBackend

class DeepSeekBackend(ChatBackend):
    def __init__(self, session_manager):
        self.token = self._load_token(session_manager)
        self.base = session_manager.get("deepseek", "api_base") or "https://api.deepseek.com/v1"
        self.model = session_manager.get("deepseek", "model") or "deepseek-chat"

    def _load_token(self, mgr):
        path = mgr.get("deepseek", "token_path")
        if path and os.path.exists(os.path.expanduser(path)):
            with open(os.path.expanduser(path)) as f:
                return f.read().strip()
        # fallback: harmony_hub style (token_provider_v2)
        try:
            import sys; sys.path.insert(0, str(Path.home() / "harmony_hub"))
            from src.token_provider_v2 import get_token
            return get_token("default")
        except Exception:
            return None

    def is_available(self):
        return bool(self.token)

    def send_message(self, message, context):
        headers = {
            "Authorization": f"Bearer {self.token}",
            "Content-Type": "application/json"
        }
        msgs = context + [{"role": "user", "content": message}]
        resp = requests.post(f"{self.base}/chat/completions",
                             json={"model": self.model, "messages": msgs},
                             headers=headers)
        resp.raise_for_status()
        return resp.json()["choices"][0]["message"]["content"]
