from google import genai
from .base import ChatBackend

class GeminiBackend(ChatBackend):
    def __init__(self, session_manager):
        key = session_manager.get("gemini", "api_key")
        self.model = session_manager.get("gemini", "model") or "gemini-2.0-flash"
        self.client = genai.Client(api_key=key) if key else None

    def is_available(self):
        return self.client is not None

    def send_message(self, message, context):
        # Gemini's history format is list of {"role": ..., "parts": [text]}
        history = []
        for m in context:
            role = "user" if m["role"] == "user" else "model"
            history.append({"role": role, "parts": [{"text": m["content"]}]})
        chat = self.client.chats.create(model=self.model, history=history)
        response = chat.send_message(message)
        return response.text
