import anthropic
from .base import ChatBackend

class ClaudeBackend(ChatBackend):
    def __init__(self, session_manager):
        key = session_manager.get("claude", "api_key")
        self.model = session_manager.get("claude", "model") or "claude-3-7-sonnet-20250219"
        self.client = anthropic.Anthropic(api_key=key) if key else None

    def is_available(self):
        return self.client is not None

    def send_message(self, message, context):
        # Anthropic expects system prompt separately; we'll keep it simple
        system = ""
        msgs = []
        for m in context:
            if m["role"] == "system":
                system = m["content"]
            else:
                msgs.append(m)
        msgs.append({"role": "user", "content": message})
        resp = self.client.messages.create(
            model=self.model,
            system=system if system else anthropic.NOT_GIVEN,
            messages=msgs,
            max_tokens=4096
        )
        return resp.content[0].text
