import json, os
from curl_cffi import requests
from .base import ChatBackend

class ColabBackend(ChatBackend):
    def __init__(self, session_manager):
        cookies_path = session_manager.get("colab", "cookies_path")
        self.notebook_id = session_manager.get("colab", "notebook_id") or "default"
        self.session = requests.Session(impersonate="chrome110")
        self._load_cookies(cookies_path)

    def _load_cookies(self, path):
        if not path or not os.path.exists(os.path.expanduser(path)):
            return
        with open(os.path.expanduser(path)) as f:
            cookies = json.load(f)
        for c in cookies:
            self.session.cookies.set(
                c["name"], c["value"],
                domain=c.get("domain", ".google.com"),
                path=c.get("path", "/")
            )

    def is_available(self):
        try:
            resp = self.session.get(
                "https://colab.research.google.com/api/contents",
                params={"id": self.notebook_id}
            )
            return resp.status_code == 200
        except Exception:
            return False

    def send_message(self, message, context):
        """Treat message as a code execution request (cell injection)."""
        # Get current notebook structure
        nb_resp = self.session.get(
            f"https://colab.research.google.com/api/contents/{self.notebook_id}"
        )
        nb = nb_resp.json()
        # Inject a new code cell with the message
        new_cell = {
            "cell_type": "code",
            "source": [message],
            "metadata": {}
        }
        nb["cells"].append(new_cell)
        # Save notebook back
        put_resp = self.session.put(
            f"https://colab.research.google.com/api/contents/{self.notebook_id}",
            json={"content": nb, "type": "notebook"}
        )
        put_resp.raise_for_status()
        # Now execute the cell (requires runtime connection; simplified)
        # Ideally we'd trigger execution via WebSocket, but for now return status.
        return f"Cell injected. Open notebook to run, or add WebSocket execution later."
PYEOF

