#!/usr/bin/env python3
import click
from core.session_manager import SessionManager
from core.chat_dispatcher import ChatDispatcher

@click.group()
def cli():
    """multi-ai-cli – l33t multi-provider AI terminal"""
    pass

@cli.command()
@click.option("--provider", "-p", default="deepseek", help="AI backend to use")
@click.option("--session", "-s", default=None, help="Session ID for context persistence")
@click.argument("prompt")
def chat(provider, session, prompt):
    mgr = SessionManager()
    dispatcher = ChatDispatcher(mgr)
    try:
        reply = dispatcher.send(provider, prompt, session)
        click.echo(reply)
    except Exception as e:
        click.echo(f"Error: {e}", err=True)

@cli.command()
@click.option("--provider", "-p", default="deepseek")
@click.option("--session", "-s", default=None)
@click.argument("prompt")
def execute(provider, session, prompt):
    """Execute code on remote runtime (e.g. Colab)"""
    # For now, identical to chat but may differentiate later
    chat.callback(provider=provider, session=session, prompt=prompt)

if __name__ == "__main__":
    cli()
PYEOF

