  const runtimeModel = typeof entry.model === "string" ? en
try.model.trim() : "";
  const runtimeProvider = typeof entry.modelProvider === "s
tring" ? entry.modelProvider.trim() : "";                  
  const runtimePresent = runtimeModel.length > 0 || runtime
Provider.length > 0;                                       
  const runtimeAligned =                                   
