lection.provider);
  if (runtimePresent && (selectionUpdated || !runtimeAligne
d)) {
    if (entry.model !== undefined) {
      delete entry.model;                                  
      updated = true;                                      
    }                                                      
    if (entry.modelProvider !== undefined) {
