export type SessionSendPolicyDecision = "allow" | "deny";

export function normalizeSendPolicy(raw?: string | null): S
essionSendPolicyDecision | undefined {                     
  const value = raw?.trim().toLowerCase();                 
  if (value === "allow") {                                 
    return "allow";
  }
  if (value === "deny") {
    return "deny";
  }                                                        
  return undefined;                                        
}

function normalizeMatchValue(raw?: string | null) {
  const value = raw?.trim().toLowerCase();                 
  return value ? value : undefined;                        
}                                                          

function stripAgentSessionKeyPrefix(key?: string): string |
 undefined {
  if (!key) {                                              
    return undefined;
  }                                                        
  const parts = key.split(":").filter(Boolean);
  // Canonical agent session keys: agent:<agentId>:<session
Key...>                                                    
  if (parts.length >= 3 && parts[0] === "agent") {
    return parts.slice(2).join(":");                       
  }
  return key;                                              
}

function deriveChannelFromKey(key?: string) {              
  const normalizedKey = stripAgentSessionKeyPrefix(key);   
  if (!normalizedKey) {                                    
    return undefined;                                      
  }
  const parts = normalizedKey.split(":").filter(Boolean);  
  if (parts.length >= 3 && (parts[1] === "group" || parts[1
] === "channel")) {                                        
    return normalizeMatchValue(parts[0]);
  }                                                        
  return undefined;
}

function deriveChatTypeFromKey(key?: string): SessionChatTy
pe | undefined {
  const chatType = deriveSessionChatType(key);
  return chatType === "unknown" ? undefined : chatType;    
