--- session-key-utils.ts ---
export type ParsedAgentSessionKey = {
  agentId: string;
  rest: string;
};

export type SessionKeyChatType = "direct" | "group" | "chan
nel" | "unknown";                                          

/**                                                        
 * Parse agent-scoped session keys in a canonical, case-ins
ensitive way.                                              
 * Returned values are normalized to lowercase for stable c
omparisons/routing.                                        
 */
export function parseAgentSessionKey(                      
  sessionKey: string | undefined | null,
): ParsedAgentSessionKey | null {                          
  const raw = (sessionKey ?? "").trim().toLowerCase();
  if (!raw) {                                              
    return null;
  }                                                        
  const parts = raw.split(":").filter(Boolean);
  if (parts.length < 3) {                                  
    return null;
  }                                                        
  if (parts[0] !== "agent") {
    return null;                                           
  }                                                        
  const agentId = parts[1]?.trim();                        
  const rest = parts.slice(2).join(":");                   
  if (!agentId || !rest) {                                 
    return null;
  }                                                        
  return { agentId, rest };
}                                                          

/**                                                        
 * Best-effort chat-type extraction from session keys acros
s canonical and legacy formats.                            
 */
export function deriveSessionChatType(sessionKey: string | 
undefined | null): SessionKeyChatType {
  const raw = (sessionKey ?? "").trim().toLowerCase();     
  if (!raw) {
    return "unknown";                                      
  }
  const scoped = parseAgentSessionKey(raw)?.rest ?? raw;   
  const tokens = new Set(scoped.split(":").filter(Boolean))
;                                                          
  if (tokens.has("group")) {
    return "group";                                        
  }
  if (tokens.has("channel")) {                             
    return "channel";
  }                                                        
  if (tokens.has("direct") || tokens.has("dm")) {
    return "direct";                                       
  }
  // Legacy Discord keys can be shaped like:               
  // discord:<accountId>:guild-<guildId>:channel-<channelId
>                                                          
  if (/^discord:(?:[^:]+:)?guild-[^:]+:channel-[^:]+$/.test
(scoped)) {                                                
    return "channel";                                      
  }                                                        
  return "unknown";                                        
}                                                          


