export const SESSION_LABEL_MAX_LENGTH = 512;               

export type ParsedSessionLabel = { ok: true; label: string 
} | { ok: false; error: string };                          

export function parseSessionLabel(raw: unknown): ParsedSess
ionLabel {
  if (typeof raw !== "string") {
    return { ok: false, error: "invalid label: must be a st
ring" };
  }
  const trimmed = raw.trim();
  if (!trimmed) {
    return { ok: false, error: "invalid label: empty" };
  }
  if (trimmed.length > SESSION_LABEL_MAX_LENGTH) {
    return {                                               
      ok: false,
      error: `invalid label: too long (max ${SESSION_LABEL_
MAX_LENGTH})`,
    };                                                     
  }
  return { ok: true, label: trimmed };                     
}

