export type SessionLifecycleEvent = {
  sessionKey: string;
  reason: string;
  parentSessionKey?: string;
  label?: string;
  displayName?: string;
};

type SessionLifecycleListener = (event: SessionLifecycleEve
nt) => void;

const SESSION_LIFECYCLE_LISTENERS = new Set<SessionLifecycl
eListener>();

export function onSessionLifecycleEvent(listener: SessionLi
fecycleListener): () => void {
  SESSION_LIFECYCLE_LISTENERS.add(listener);
  return () => {                                           
    SESSION_LIFECYCLE_LISTENERS.delete(listener);          
  };                                                       
}

export function emitSessionLifecycleEvent(event: SessionLif
ecycleEvent): void {
  for (const listener of SESSION_LIFECYCLE_LISTENERS) {
    try {                                                  
      listener(event);
    } catch {
      // Best-effort, do not propagate listener errors.    
    }
  }                                                        
}

