import json                                                
from typing import Callable, List, Optional
from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse, StreamingRespon
se

import time
import uuid
from pydantic import BaseModel, field_validator            
import uvicorn
import logging

from chapito.config import Config


async def generate_json_stream(data: dict):
    data["choices"][0]["delta"] = data["choices"][0]["messa
ge"]                                                       
    del data["choices"][0]["message"]
    yield f"data: {json.dumps(data)}\n\n"
    yield "data: [DONE]\n\n"                               


class Message(BaseModel):                                  
    role: str
    content: str

    @field_validator("content", mode="before")             
    def transform_content(cls, value):                     
        if isinstance(value, list):
            text_parts = [item["text"] for item in value if
 item.get("type") == "text"]
            return "\n\n".join(text_parts)
        return value


class ChatRequest(BaseModel):
    model: str
    messages: List[Message]
    temperature: Optional[float] = None                    
    max_tokens: Optional[int] = None
    top_p: Optional[float] = None                          
    frequency_penalty: Optional[float] = None
    presence_penalty: Optional[float] = None


app = FastAPI()

last_chat_messages: List[str] = []


def find_index_from_end(lst: List[Message], values: List[st
r]) -> int:
    for i in range(len(lst) - 1, -1, -1):
        message = lst[i]
        if message.content.strip() in values:
            return i
    return -1


@app.exception_handler(404)
async def not_found_handler(request: Request, exc: HTTPExce
ption):
    return JSONResponse(status_code=404, content={"message"
: "Undefined route", "requested_url": request.url.path})


