import { loadConfig } from "../io.js";
import { resolveStorePath } from "./paths.js";
import { loadSessionStore } from "./store.js";             

/**
 * Extract deliveryContext and threadId from a sessionKey.
 * Supports both :thread: (most channels) and :topic: (Tele
gram).
 */
export function parseSessionThreadInfo(sessionKey: string |
 undefined): {                                             
  baseSessionKey: string | undefined;
  threadId: string | undefined;                            
} {                                                        
  if (!sessionKey) {
    return { baseSessionKey: undefined, threadId: undefined
 };
  }
  const topicIndex = sessionKey.lastIndexOf(":topic:");
  const threadIndex = sessionKey.lastIndexOf(":thread:");
  const markerIndex = Math.max(topicIndex, threadIndex);
  const marker = topicIndex > threadIndex ? ":topic:" : ":t
hread:";

  const baseSessionKey = markerIndex === -1 ? sessionKey : 
sessionKey.slice(0, markerIndex);                          
  const threadIdRaw =
    markerIndex === -1 ? undefined : sessionKey.slice(marke
rIndex + marker.length);                                   
  const threadId = threadIdRaw?.trim() || undefined;       
  return { baseSessionKey, threadId };                     
}                                                          

export function extractDeliveryInfo(sessionKey: string | un
defined): {                                                
  deliveryContext: { channel?: string; to?: string; account
Id?: string } | undefined;
  threadId: string | undefined;                            
} {
  const { baseSessionKey, threadId } = parseSessionThreadIn
fo(sessionKey);                                            
  if (!sessionKey || !baseSessionKey) {                    
    return { deliveryContext: undefined, threadId };
  }                                                        

  let deliveryContext: { channel?: string; to?: string; acc
ountId?: string } | undefined;
  try {                                                    
    const cfg = loadConfig();
    const storePath = resolveStorePath(cfg.session?.store);
    const store = loadSessionStore(storePath);
    let entry = store[sessionKey];                         
    if (!entry?.deliveryContext && baseSessionKey !== sessi
onKey) {                                                   
      entry = store[baseSessionKey];
    }                                                      
    if (entry?.deliveryContext) {                          
      deliveryContext = {
        channel: entry.deliveryContext.channel,            
        to: entry.deliveryContext.to,
        accountId: entry.deliveryContext.accountId,        
      };
    }                                                      
  } catch {
    // ignore: best-effort
  }                                                        
  return { deliveryContext, threadId };                    
}                                                          

