): ExplicitSessionKeyNormalizer | undefined {              
  const normalizedProvider = ctx.Provider?.trim().toLowerCa
se();
  const normalizedSurface = ctx.Surface?.trim().toLowerCase
();                                                        
  const normalizedFrom = (ctx.From ?? "").trim().toLowerCas
e();                                                       
  return EXPLICIT_SESSION_KEY_NORMALIZERS.find((entry) =>
    entry.matches({                                        
      sessionKey,                                          
      provider: normalizedProvider,
      surface: normalizedSurface,
      from: normalizedFrom,
    }),
  )?.normalize;
}                                                          

