import { resolveSessionFilePath } from "./paths.js";       
import { updateSessionStore } from "./store.js";
import type { SessionEntry } from "./types.js";            

export async function resolveAndPersistSessionFile(params: 
{
  sessionId: string;
  sessionKey: string;                                      
  sessionStore: Record<string, SessionEntry>;              
  storePath: string;                                       
  sessionEntry?: SessionEntry;
  agentId?: string;                                        
  sessionsDir?: string;                                    
  fallbackSessionFile?: string;                            
  activeSessionKey?: string;
}): Promise<{ sessionFile: string; sessionEntry: SessionEnt
ry }> {
  const { sessionId, sessionKey, sessionStore, storePath } 
= params;
  const baseEntry = params.sessionEntry ??
    sessionStore[sessionKey] ?? { sessionId, updatedAt: Dat
e.now() };                                                 
  const fallbackSessionFile = params.fallbackSessionFile?.t
rim();                                                     
  const entryForResolve =
    !baseEntry.sessionFile && fallbackSessionFile          
      ? { ...baseEntry, sessionFile: fallbackSessionFile }
      : baseEntry;
  const sessionFile = resolveSessionFilePath(sessionId, ent
ryForResolve, {
    agentId: params.agentId,
    sessionsDir: params.sessionsDir,                       
  });                                                      
  const persistedEntry: SessionEntry = {
    ...baseEntry,                                          
    sessionId,
    updatedAt: Date.now(),
    sessionFile,                                           
  };                                                       
  if (baseEntry.sessionId !== sessionId || baseEntry.sessio
nFile !== sessionFile) {                                   
    sessionStore[sessionKey] = persistedEntry;
    await updateSessionStore(                              
      storePath,
      (store) => {
        store[sessionKey] = {
          ...store[sessionKey],                            
          ...persistedEntry,                               
        };
      },
      params.activeSessionKey ? { activeSessionKey: params.
activeSessionKey } : undefined,
    );                                                     
    return { sessionFile, sessionEntry: persistedEntry };  
  }                                                        
  sessionStore[sessionKey] = persistedEntry;               
  return { sessionFile, sessionEntry: persistedEntry };    
}                                                          

