function resolvePruneAfterMs(maintenance?: SessionMaintenan
ceConfig): number {                                        
  const raw = maintenance?.pruneAfter ?? maintenance?.prune
Days;
  if (raw === undefined || raw === null || raw === "") {
    return DEFAULT_SESSION_PRUNE_AFTER_MS;                 
  }
  try {                                                    
    return parseDurationMs(String(raw).trim(), { defaultUni
t: "d" });                                                 
  } catch {                                                
    return DEFAULT_SESSION_PRUNE_AFTER_MS;                 
  }                                                        
}

function resolveRotateBytes(maintenance?: SessionMaintenanc
eConfig): number {                                         
  const raw = maintenance?.rotateBytes;                    
  if (raw === undefined || raw === null || raw === "") {
    return DEFAULT_SESSION_ROTATE_BYTES;                   
  }
  try {
    return parseByteSize(String(raw).trim(), { defaultUnit:
 "b" });                                                   
  } catch {                                                
    return DEFAULT_SESSION_ROTATE_BYTES;                   
  }                                                        
}                                                          

