import type { SessionEntry } from "./types.js";

export function applySessionStoreMigrations(store: Record<s
tring, SessionEntry>): void {                              
  // Best-effort migration: message provider → channel nami
ng.                                                        
  for (const entry of Object.values(store)) {
    if (!entry || typeof entry !== "object") {             
      continue;                                            
    }                                                      
    const rec = entry as unknown as Record<string, unknown>
;                                                          
    if (typeof rec.channel !== "string" && typeof rec.provi
der === "string") {                                        
      rec.channel = rec.provider;
      delete rec.provider;                                 
    }
    if (typeof rec.lastChannel !== "string" && typeof rec.l
astProvider === "string") {                                
      rec.lastChannel = rec.lastProvider;
      delete rec.lastProvider;                             
    }

    // Best-effort migration: legacy `room` field → `groupC
hannel` (keep value, prune old key).                       
    if (typeof rec.groupChannel !== "string" && typeof rec.
room === "string") {                                       
      rec.groupChannel = rec.room;                         
      delete rec.room;                                     
    } else if ("room" in rec) {                            
      delete rec.room;                                     
    }                                                      
  }                                                        
}                                                          

