#!/usr/bin/env python3
"""WebSocket bridge: Termux <-> Firefox Tampermonkey for Mistral"""
import asyncio, json, sys
from pathlib import Path
import websockets

BROWSER_WS = None
RESPONSE_FUTURE = None
PORT = 9876

async def handle_browser(websocket):
    global BROWSER_WS
    BROWSER_WS = websocket
    print("[bridge] Browser connected")
    try:
        async for msg in websocket:
            data = json.loads(msg)
            if data.get("type") == "token":
                Path.home().joinpath(".multi-ai-tokens/mistral_token.txt").write_text(data["token"])
                print("[bridge] Token saved")
            elif data.get("type") == "response":
                global RESPONSE_FUTURE
                if RESPONSE_FUTURE and not RESPONSE_FUTURE.done():
                    RESPONSE_FUTURE.set_result(data.get("text", ""))
                else:
                    print(data.get("text", ""), end="", flush=True)
            elif data.get("type") == "done":
                if RESPONSE_FUTURE and not RESPONSE_FUTURE.done():
                    RESPONSE_FUTURE.set_result(RESPONSE_FUTURE.result() if hasattr(RESPONSE_FUTURE, 'result') else "")
                print()
    finally:
        BROWSER_WS = None
        print("[bridge] Browser disconnected")

async def handle_cli(websocket):
    global BROWSER_WS, RESPONSE_FUTURE
    async for msg in websocket:
        if not BROWSER_WS:
            await websocket.send(json.dumps({"error": "Browser not connected"}))
            continue
        data = json.loads(msg)
        prompt = data.get("prompt", "")
        RESPONSE_FUTURE = asyncio.get_event_loop().create_future()
        await BROWSER_WS.send(json.dumps({"type": "prompt", "text": prompt}))
        try:
            result = await asyncio.wait_for(RESPONSE_FUTURE, timeout=120)
        except asyncio.TimeoutError:
            result = "[Timeout]"
        await websocket.send(json.dumps({"response": result}))

async def main():
    print(f"[bridge] Starting on ws://127.0.0.1:{PORT}")
    async with websockets.serve(handle_browser, "127.0.0.1", PORT):
        await asyncio.Future()  # run forever

if __name__ == "__main__":
    asyncio.run(main())
