```javascript
// ==UserScript==
// @name         Mistral Bridge for multi-ai-cli
// @namespace    http://tampermonkey.net/
// @version      1.0
// @description  Intercepts Mistral API and bridges to local Python server
// @match        https://chat.mistral.ai/*
// @grant        none
// @run-at       document-start
// ==/UserScript==

(function() {
    'use strict';
    const BRIDGE_URL = 'ws://127.0.0.1:9876';
    let ws = null;
    let sessionToken = null;
    let connectTimer = null;

    function connect() {
        if (ws && ws.readyState === WebSocket.OPEN) return;
        try {
            ws = new WebSocket(BRIDGE_URL);
            ws.onopen = () => {
                console.log('[MistralBridge] Connected');
                // Send token if we have it
                if (sessionToken) {
                    ws.send(JSON.stringify({type: 'token', token: sessionToken}));
                }
            };
            ws.onclose = () => {
                console.log('[MistralBridge] Disconnected, reconnecting in 5s');
                connectTimer = setTimeout(connect, 5000);
            };
            ws.onerror = (e) => {
                console.log('[MistralBridge] Connection error');
            };
            ws.onmessage = async (event) => {
                const data = JSON.parse(event.data);
                if (data.type === 'prompt') {
                    const response = await sendToMistral(data.text);
                    ws.send(JSON.stringify({type: 'response', text: response}));
                    ws.send(JSON.stringify({type: 'done'}));
                }
            };
        } catch(e) {
            connectTimer = setTimeout(connect, 5000);
        }
    }

    // Intercept fetch to capture token AND raw API calls
    const origFetch = window.fetch;
    window.fetch = async function(...args) {
        const [url, opts] = args;
        // Capture Bearer token from any request
        if (opts && opts.headers) {
            const headers = new Headers(opts.headers);
            const auth = headers.get('Authorization') || headers.get('authorization');
            if (auth && auth.startsWith('Bearer ') && !sessionToken) {
                sessionToken = auth.replace('Bearer ', '');
                console.log('[MistralBridge] Token captured');
                if (ws && ws.readyState === WebSocket.OPEN) {
                    ws.send(JSON.stringify({type: 'token', token: sessionToken}));
                }
            }
        }
        return origFetch.apply(this, args);
    };

    // Function to send a prompt and get full response (handles SSE)
    async function sendToMistral(prompt) {
        // Find the chat input and submit
        const textarea = document.querySelector('textarea[placeholder*="Ask"]') ||
                        document.querySelector('div[contenteditable="true"]');
        const submitBtn = document.querySelector('button[aria-label*="Send"], button[type="submit"]');

        if (!textarea || !submitBtn) {
            return "Error: Mistral chat UI not found. Please navigate to https://chat.mistral.ai";
        }

        // Type the prompt
        textarea.focus();
        if (textarea.tagName === 'TEXTAREA') {
            textarea.value = prompt;
            textarea.dispatchEvent(new Event('input', { bubbles: true }));
        } else {
            textarea.innerText = prompt;
            textarea.dispatchEvent(new Event('input', { bubbles: true }));
        }

        // Click submit
        submitBtn.click();

        // Wait for the response to appear and stabilize
        return await new Promise((resolve) => {
            let lastText = '';
            let stableCount = 0;
            const checkInterval = setInterval(() => {
                const messages = document.querySelectorAll('div.prose, [class*="message"]');
                const lastMsg = messages[messages.length - 1];
                const currentText = lastMsg ? lastMsg.innerText : '';
                if (currentText === lastText && currentText.length > 0) {
                    stableCount++;
                    if (stableCount >= 3) { // stable for 3 intervals (1.5s)
                        clearInterval(checkInterval);
                        resolve(currentText);
                    }
                } else {
                    lastText = currentText;
                    stableCount = 0;
                }
            }, 500);
            // Timeout after 120s
            setTimeout(() => {
                clearInterval(checkInterval);
                resolve(lastText || "[No response]");
            }, 120000);
        });
    }

    // Start connection
    connect();
})();
