            }
        }
        return origFetch.apply(this, args);
    };

    // Send a prompt via the DOM
    async function sendPrompt(text) {
        const textarea = document.querySelector('textarea[placeholder*="Ask"]') ||
                        document.querySelector('div[contenteditable="true"]');
        const submitBtn = document.querySelector('button[aria-label*="Send"], button[type="submit"]');
        if (!textarea || !submitBtn) {
            post({type: 'response', text: 'Error: Mistral UI not ready'});
            return;
        }
        // Type prompt
        textarea.focus();
        if (textarea.tagName === 'TEXTAREA' || textarea.tagName === 'INPUT') {
            textarea.value = text;
            textarea.dispatchEvent(new Event('input', { bubbles: true }));
        } else {
            textarea.innerText = text;
            textarea.dispatchEvent(new Event('input', { bubbles: true }));
        }
        submitBtn.click();

        // Wait for response to appear and stabilize
        let lastText = '';
        let stable = 0;
        const response = await new Promise((resolve) => {
            const interval = setInterval(() => {
                const msgs = document.querySelectorAll('div.prose, [class*="message"]');
                const last = msgs[msgs.length - 1];
                const cur = last ? last.innerText : '';
                if (cur === lastText && cur.length > 0) {
                    stable++;
                    if (stable >= 4) {
                        clearInterval(interval);
                        resolve(cur);
                    }
                } else {
                    lastText = cur;
                    stable = 0;
                }
            }, 500);
            setTimeout(() => { clearInterval(interval); resolve(lastText || '[No response]'); }, 120000);
        });
        post({type: 'response', text: response});
    }

    // Poll for prompts
    function poll() {
        GM_xmlhttpRequest({
            method: 'GET',
            url: BRIDGE + '/poll',
            onload: function(resp) {
                if (resp.status === 200) {
                    const data = JSON.parse(resp.responseText);
                    if (data.prompt) {
                        console.log('[MistralBridge] Got prompt:', data.prompt);
                        sendPrompt(data.prompt);
                    }
                }
            },
            onerror: function() {},
            ontimeout: function() {}
        });
        pollTimer = setTimeout(poll, 1000);
    }

    // Start
    if (sessionToken) post({type: 'token', token: sessionToken});
    poll();
    console.log('[MistralBridge] Started');
})();
```

