## 3. Update the backend to use HTTP instead of WebSocket

```bash
cat > ~/multi-ai-cli/backends/mistral_web.py << 'PYEOF'
import json, requests
from .base import ChatBackend

BRIDGE_URL = "http://127.0.0.1:9876"

class MistralWebBackend(ChatBackend):
    def __init__(self, session_manager=None):
        pass

    def is_available(self):
        return True

    def send_message(self, message: str, context: list[dict]) -> str:
        # Send prompt to bridge
        resp = requests.post(BRIDGE_URL,
                             json={"type": "prompt", "text": message},
                             timeout=130)
        if resp.status_code == 200:
            return resp.json().get("response", "")
        return f"Bridge error: {resp.status_code}"
PYEOF
